void ui_page_Mic1_exit(uint8_t del)
{
    if(del)
    {

    }
    else
    {

    }
    SendBuf[9] = 0x00;//退出当前页面，让从机关闭LED灯
    MasterSendExample(0x22);
}

void ui_page_Mic1_clean(void)
{
    lv_mem_free(ObjsCt);
    ObjsCt = NULL;
}

void ui_page_Mic1_request(uint32_t delay)
{
    switch(ui_pmanagerCt.id_tar)
    {

        case UI_PAGE_SEL_1:
            break;

        default:
            ui_pmanager_switch(UI_PAGE_SEL_1, delay, true);
            break;
    }
    SendBuf[9] = 0x01;//进入当前页面，让从机开启LED灯
    MasterSendExample(0x22);
}


