void ui_page_Mic1_encoder_up(void)
{
    if(ObjsCt == NULL) return;
    
    if(ArgsCt.edit_mode == 0)
    {
        switch(ArgsCt.focus_target)
        {
            case 0:
                lv_obj_set_style_border_color(ObjsCt->ui_select_panel, lv_color_hex(0xFFFFFF), LV_PART_MAIN | LV_STATE_DEFAULT);
                break;
            case 1:
                lv_obj_set_style_border_color(ObjsCt->ui_gain_panel, lv_color_hex(0xFFFFFF), LV_PART_MAIN | LV_STATE_DEFAULT);
                break;
            case 2:
                lv_obj_set_style_border_color(ObjsCt->ui_phantom_panel, lv_color_hex(0xFFFFFF), LV_PART_MAIN | LV_STATE_DEFAULT);
                break;
            case 3:
                lv_obj_set_style_border_color(ObjsCt->ui_fx_panel, lv_color_hex(0xFFFFFF), LV_PART_MAIN | LV_STATE_DEFAULT);
                break;
            case 4: lv_obj_set_style_border_color(ObjsCt->ui_fbe_panel, lv_color_hex(0xFFFFFF), LV_PART_MAIN | LV_STATE_DEFAULT);
                break;
            case 5: lv_obj_set_style_border_color(ObjsCt->ui_hi_panel, lv_color_hex(0xFFFFFF), LV_PART_MAIN | LV_STATE_DEFAULT);
                break;
            case 6: lv_obj_set_style_border_color(ObjsCt->ui_mid_panel, lv_color_hex(0xFFFFFF), LV_PART_MAIN | LV_STATE_DEFAULT);
                break;
            case 7: lv_obj_set_style_border_color(ObjsCt->ui_low_panel, lv_color_hex(0xFFFFFF), LV_PART_MAIN | LV_STATE_DEFAULT);
                break;
            case 8: lv_obj_set_style_border_color(ObjsCt->ui_hpf_panel, lv_color_hex(0xFFFFFF), LV_PART_MAIN | LV_STATE_DEFAULT);
                break;
            case 9: lv_obj_set_style_border_color(ObjsCt->ui_pan_panel, lv_color_hex(0xFFFFFF), LV_PART_MAIN | LV_STATE_DEFAULT);
                break;
        }
        
        if(ArgsCt.focus_target < 9)
        {
            ArgsCt.focus_target++;
        }
        else
        {
            ArgsCt.focus_target = 0;
        }
        
        switch(ArgsCt.focus_target)
        {
            case 0:
                lv_obj_set_style_border_color(ObjsCt->ui_select_panel, lv_color_hex(0x00FF00), LV_PART_MAIN | LV_STATE_DEFAULT);
                break;
            case 1:
                lv_obj_set_style_border_color(ObjsCt->ui_gain_panel, lv_color_hex(0x00FF00), LV_PART_MAIN | LV_STATE_DEFAULT);
                break;
            case 2:
                lv_obj_set_style_border_color(ObjsCt->ui_phantom_panel, lv_color_hex(0x00FF00), LV_PART_MAIN | LV_STATE_DEFAULT);
                break;
            case 3:
                lv_obj_set_style_border_color(ObjsCt->ui_fx_panel, lv_color_hex(0x00FF00), LV_PART_MAIN | LV_STATE_DEFAULT);
                break;
            case 4: 
                lv_obj_set_style_border_color(ObjsCt->ui_fbe_panel, lv_color_hex(0x00FF00), LV_PART_MAIN | LV_STATE_DEFAULT);
                break;
            case 5: 
                lv_obj_set_style_border_color(ObjsCt->ui_hi_panel, lv_color_hex(0x00FF00), LV_PART_MAIN | LV_STATE_DEFAULT);
                break;
            case 6: 
                lv_obj_set_style_border_color(ObjsCt->ui_mid_panel, lv_color_hex(0x00FF00), LV_PART_MAIN | LV_STATE_DEFAULT);
                break;
            case 7: 
                lv_obj_set_style_border_color(ObjsCt->ui_low_panel, lv_color_hex(0x00FF00), LV_PART_MAIN | LV_STATE_DEFAULT);
                break;
            case 8: 
                lv_obj_set_style_border_color(ObjsCt->ui_hpf_panel, lv_color_hex(0x00FF00), LV_PART_MAIN | LV_STATE_DEFAULT);
                break;
            case 9: 
                lv_obj_set_style_border_color(ObjsCt->ui_pan_panel, lv_color_hex(0x00FF00), LV_PART_MAIN | LV_STATE_DEFAULT);
                break;
        }
        
    }
    else 
    {
        switch(ArgsCt.focus_target)
        {
            case 1: // gain panel
                if(ArgsCt.gain_args < sizeof(gain_args_table)/sizeof(gain_args_table[0]) - 1)
                {
                    ArgsCt.gain_args++;
                    ui_page_mic1_gain_arg_refresh(ArgsCt.gain_args);
                }
                break;
            case 2: // phantom panel - ON/OFF switch
                if(ArgsCt.phantom_args < 1)  // 0=OFF, 1=ON
                {
                    ArgsCt.phantom_args++;
                    ui_page_mic1_phantom_arg_refresh(ArgsCt.phantom_args);
                }
                break;
            case 3: // fx panel
                if(ArgsCt.fx_args < sizeof(fx_args_table)/sizeof(fx_args_table[0]) - 1)
                {
                    ArgsCt.fx_args++;
                    ui_page_mic1_fx_arg_refresh(ArgsCt.fx_args);
                }
                break;
            case 4: // fbe panel (MIC FBE)
                if(ArgsCt.fbe_args < sizeof(fbe_args_table)/sizeof(fbe_args_table[0]) - 1)
                {
                    ArgsCt.fbe_args++;
                    ui_page_mic1_fbe_arg_refresh(ArgsCt.fbe_args);
                }
                break;
            case 5: // hi panel
                if(ArgsCt.hi_args < sizeof(eq_args_table)/sizeof(eq_args_table[0]) - 1)
                {
                    ArgsCt.hi_args++;
                    ui_page_mic1_hi_arg_refresh(ArgsCt.hi_args);
                }
                break;
            case 6: // mid panel
                if(ArgsCt.mid_args < sizeof(eq_args_table)/sizeof(eq_args_table[0]) - 1)
                {
                    ArgsCt.mid_args++;
                    ui_page_mic1_mid_arg_refresh(ArgsCt.mid_args);
                }
                break;
            case 7: // low panel
                if(ArgsCt.low_args < sizeof(eq_args_table)/sizeof(eq_args_table[0]) - 1)
                {
                    ArgsCt.low_args++;
                    ui_page_mic1_low_arg_refresh(ArgsCt.low_args);
                }
                break;
            case 8: // pan panel (MIC HPF: 80Hz/120Hz/200Hz)
                if(ArgsCt.hpf_args < sizeof(hpf_args_table)/sizeof(hpf_args_table[0]) - 1)
                {
                    ArgsCt.hpf_args++;
                    ui_page_mic1_hpf_arg_refresh(ArgsCt.hpf_args);
                }
                break;
            case 9: // pan2 panel (PAN: L/R)
                if(ArgsCt.pan_args < 2)  // 0=不选, 1=L, 2=R
                {
                    ArgsCt.pan_args++;
                    ui_page_mic1_pan_arg_refresh(ArgsCt.pan_args);
                }
                break;
        }
    }
}

