void ui_page_Mic1_encoder_ok(void)
{
    if(ObjsCt == NULL) return;
    
    if(ArgsCt.focus_target == 2)
    {
        if(ArgsCt.edit_mode == 0)
        {
            ArgsCt.edit_mode = 1;
            lv_obj_set_style_text_color(ObjsCt->ui_phantom_args, lv_color_hex(0xFFA500), LV_PART_MAIN | LV_STATE_DEFAULT);
        }
        else
        {
            ArgsCt.edit_mode = 0;
            lv_obj_set_style_text_color(ObjsCt->ui_phantom_args, lv_color_hex(0xFFFFFF), LV_PART_MAIN | LV_STATE_DEFAULT);
        }
        return;
    }
    
    ArgsCt.edit_mode = !ArgsCt.edit_mode;
    
    lv_color_t text_color = ArgsCt.edit_mode ? lv_color_hex(0xFFA500) : lv_color_hex(0xFFFFFF);
    
    switch(ArgsCt.focus_target)
    {
        case 0:
            lv_obj_set_style_text_color(ObjsCt->ui_select_args, text_color, LV_PART_MAIN | LV_STATE_DEFAULT);
            break;
        case 1:
            lv_obj_set_style_text_color(ObjsCt->ui_gain_args, text_color, LV_PART_MAIN | LV_STATE_DEFAULT);
            break;
        case 2:
            lv_obj_set_style_text_color(ObjsCt->ui_phantom_args, text_color, LV_PART_MAIN | LV_STATE_DEFAULT);
            break;
        case 3:
            lv_obj_set_style_text_color(ObjsCt->ui_fx_args, text_color, LV_PART_MAIN | LV_STATE_DEFAULT);
            break;
        case 4:
            lv_obj_set_style_text_color(ObjsCt->ui_fbe_args, text_color, LV_PART_MAIN | LV_STATE_DEFAULT);
            break;
        case 5:
            lv_obj_set_style_text_color(ObjsCt->ui_hi_args, text_color, LV_PART_MAIN | LV_STATE_DEFAULT);
            break;
        case 6:
            lv_obj_set_style_text_color(ObjsCt->ui_mid_args, text_color, LV_PART_MAIN | LV_STATE_DEFAULT);
            break;
        case 7:
            lv_obj_set_style_text_color(ObjsCt->ui_low_args, text_color, LV_PART_MAIN | LV_STATE_DEFAULT);
            break;
        case 8:
            lv_obj_set_style_text_color(ObjsCt->ui_hpf_args, text_color, LV_PART_MAIN | LV_STATE_DEFAULT);
            break;
        case 9:
            lv_obj_set_style_text_color(ObjsCt->ui_pan_args, text_color, LV_PART_MAIN | LV_STATE_DEFAULT);
            break;
    }
}
